contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive the play function once with a ticket payment and assert that when a win occurs,
    // the pot is fully cleared (pot == 0). This holds for original P but is violated by M
    // which leaves pot == FEE_AMOUNT.
    function runTest(uint256 ticketAmount) public payable {
        // Preconditions: caller must supply the ticket amount as msg.value to this function.
        // We do not read msg.value per instructions; instead require caller passed correct Ether to this contract.
        require(address(this).balance >= ticketAmount, "contract lacks funds");
        // The contract C expects exactly TICKET_AMOUNT; we forward the provided ticketAmount.
        // First, call play by forwarding Ether to c.
        c.play{value: ticketAmount}();

        // Observe pot via public getter and assert it's zero after a winning play.
        // Because randomness may make the play not a win, we only assert the implication:
        // if pot is less than ticketAmount then a win occurred and pot must be zero.
        // This captures that on a win the pot is cleared entirely (P) but M would leave the fee.
        uint potAfter = c.pot();

        // If a win happened, pot should be 0. Detecting a win: when pot < ticketAmount we know the player received funds
        // and pot was reduced; in original P that means pot == 0. Mutant M leaves pot == fee (>0), violating this.
        if (potAfter < ticketAmount) {
            assert(potAfter == 0);
        }
    }

    // Allow the test contract to receive Ether used for forwarding to c.
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // must send exactly the ticket amount to play
        uint amt = 10;
        require(address(this).balance >= amt);
        c.play{value: amt}();
        // If a payout occurred to the caller then the pot must be zero.
        // We detect payout having occurred by checking that address(c).balance is less than amt + address(this).balance
        // but simpler and robust: after play the pot (public) must be either 0 or equal to fee only in mutant;
        // The correct contract always clears pot to 0 after a winning play, so assert pot == 0.
        assert(c.pot() == 0);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // send an exact ticket amount so the call proceeds
    function run(uint ticket) public payable {
        require(ticket == 10);
        require(address(this).balance >= ticket);
        c.play{value: ticket}();
        // If the caller was paid out some ether (i.e., address(this).balance increased by >0 excluding our sent ticket), then pot must be zero
        // We cannot observe transfers directly, but we can observe address(c).balance and c.pot(). For original contract when random==0,
        // the pot is cleared to 0; the mutant leaves the fee (non-zero). So require that whenever c.pot() is <= c.FEE_AMOUNT() it must in fact be 0.
        // Formulated as: c.pot() * (c.pot() - 0) == 0 is trivial; instead assert c.pot() != c.FEE_AMOUNT() to catch the mutant.
        // More robust: assert that pot is zero whenever address(c).balance is less than ticket (meaning a payout occurred).
        // After our play, if a payout to caller happened, the contract's balance decreases by (paid to caller), making address(c).balance < ticket + address(c).balance_before_call.
        // However we cannot read the prior balance; instead observe that when payout happens pot==0 in original but pot==FEE_AMOUNT in mutant. So assert pot != c.FEE_AMOUNT().
        assert(c.pot() != c.FEE_AMOUNT());
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        require(address(this).balance >= 10);
        // buy one ticket: TICKET_AMOUNT is 10 in C
        c.play{value: 10}();
        // If the caller received a payout, then pot should be zero in the original contract.
        // We observe whether this contract (the caller) has larger balance than before by checking
        // that c transferred any funds to this contract: detect by comparing address(this).balance
        // But we can't read the previous balance after the call, so instead we reason via public getter:
        // C has public pot; if payout to caller occurred then pot must be 0 in original.
        // Assert: if this caller's address now has a nonzero gain relative to c's bank fee logic,
        // then c.pot() == 0. We approximate "caller received any payout" by checking that pot is less than 10 (it was increased by 10 then possibly emptied).
        // For the original contract, when a payout happens pot becomes 0, so pot < 10 implies pot == 0.
        uint potAfter = c.pot();
        // General rule: if potAfter < 10 then potAfter == 0
        assert(!(potAfter < 10) || (potAfter == 0));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint ticket) public payable {
        // require the caller supplies exactly the ticket price and the test has enough balance
        require(ticket == 10, "must send exact ticket amount");
        require(address(this).balance >= ticket, "insufficient balance to send ticket");

        // call play with exact ticket amount; this may transfer out to msg.sender (this contract)
        c.play{value: ticket}();

        // After a winning payout, original contract ensures the contract's remaining balance equals the fee amount (1)
        // We observe address(c).balance and assert it equals FEE_AMOUNT when this call resulted in a nonzero payout to the caller.
        // We cannot directly see whether this call transferred to us, but we can check our balance increased by >0.
        // Compute whether we received any payout by comparing current balance to before; however we didn't record before —
        // Instead, require that this contract's balance is not zero to ensure a win happened for the test scenario.
        // The general assertion: if this contract has nonzero balance after play (meaning it received payout), then address(c).balance == 1
        if (address(this).balance > 0) {
            assert(address(c).balance == 1);
        } else {
            // If we didn't receive a payout, then nothing to assert about c (but assert a tautology about params to satisfy single assert)
            assert(ticket == 10);
        }
    }
    receive() external payable { }
}

