    function testFuzz_property(address player) public {
        // admissible domain: player must be non-zero and not the bank (deployed test contract)
        vm.assume(player != address(0));
        vm.assume(player != address(this));

        // ensure player has enough ETH to buy a ticket
        uint256 ticket = 10;
        vm.deal(player, ticket);

        // make the call as the fuzzed player sending exactly the ticket amount
        vm.prank(player);
        c.play{value: ticket}();

        // After a completed play(), the correct contract's pot must be either 0 (if a payout happened)
        // or >= TICKET_AMOUNT (if no payout happened and pot accumulated). The mutant can break this
        // by leaving pot == 1 (FEE_AMOUNT) after paying out. So assert pot != FEE_AMOUNT.
