pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the caller address so the fuzzer can find randomness timing that triggers the payout branch
    function testFuzz_property(address caller) public {
        // admissible domain: caller must be non-zero and not the contract itself
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        uint ticket = 10; // matches C.TICKET_AMOUNT
        // fund the caller so it can send the ticket
        vm.deal(caller, ticket);

        // record state before
        uint pot_before = c.pot();
        uint balance_before = address(c).balance;

        // perform the payable call from the fuzzed caller
        vm.prank(caller);
        // call play with exactly ticket value
        c.play{value: ticket}();

        // record state after
        uint pot_after = c.pot();
        uint balance_after = address(c).balance;

        // Compute the observed decrease in contract balance (if any)
        uint balance_decrease = 0;
        if (balance_before > balance_after) {
            balance_decrease = balance_before - balance_after;
        }

        // If there was a winning payout, the reference implementation transfers (pot_before + ticket - FEE_AMOUNT)
        // out and then sets pot to 0. Thus when a payout happened we expect pot_after == 0.
        // We express a general rule: if the contract's balance decreased by at least (pot_before + ticket - 1),
        // then pot_after must be zero. This reads only public getters and address(c).balance.
        // Single assertion: the correct contract always satisfies this; the mutant leaves pot == FEE_AMOUNT
        // while the balance already decreased, so the assertion will fail on the mutant for some inputs.

        // Note: fee amount is 1 per contract source
        uint expected_payout = pot_before + ticket - 1;

        // If the balance drop is >= expected_payout then a payout occurred; require pot_after == 0 in that case.
        if (balance_decrease >= expected_payout) {
            assertTrue(pot_after == 0);
        } else {
            // Otherwise, no strong requirement (to keep domain wide). Still assert something true about pot monotonicity:
            // pot after cannot be less than pot_before (except when payout happened), but we avoid extra assertions to keep single assert requirement.
            assertTrue(true);
        }
    }
}

