contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // single public test function
    // params:
    // initialCallerBalance - must be >= ticket (the caller supplies Ether to send)
    // ticketAmt - amount to send to play (should equal C.TICKET_AMOUNT to avoid revert)
    function runTest(uint initialCallerBalance, uint ticketAmt) public payable {
        // ensure this test contract has enough balance to pay for the ticket
        require(address(this).balance >= ticketAmt, "insufficient test contract balance");

        // record balances before playing
        uint bankBefore = address(c.bank()).balance;
        uint potBefore = c.pot();
        uint selfBefore = address(this).balance;

        // perform the play call that may reset pot and transfer funds
        c.play{value: ticketAmt}();

        // observe balances after
        uint bankAfter = address(c.bank()).balance;
        uint potAfter = c.pot();
        uint selfAfter = address(this).balance;

        // compute observed received by this contract (caller) and fee paid to bank
        uint receivedByCaller = 0;
        if (selfAfter > selfBefore) { receivedByCaller = selfAfter - selfBefore; }
        uint feePaid = 0;
        if (bankAfter > bankBefore) { feePaid = bankAfter - bankBefore; }

        // General rule: if caller received any payout this call, then pot must have been reset to 0 afterwards.
        // This distinguishes original (payout when random==0) from mutant (payout when random==1) because for
        // the same observed payout occurrence the pot reset behavior differs depending on the branch condition.
        assert(receivedByCaller == 0 || potAfter == 0);
    }

    // allow the contract to receive Ether for funding the tests
    receive() external payable {}
}

