        // clear observation flag
        __obsd = false;
        __snap = 0;
        // call play sending the ticket amount; difference is observable during the external transfers inside play
        c.play{value: amount}();
        // After the external call, the observation must have been captured in receive() during the payout path.
        // On the correct contract, the caller does NOT get paid the pot mid-call, so the pot observed MID-call must be > 0.
        assert(__obsd && __snap > 0);
    }

    // receive will be invoked if play transfers Ether to this contract (i.e., caller was paid mid-call).
    // capture c.pot() via its public getter while in the receive context (MID-call observation)
    receive() external payable {
        if (!__obsd) {
            __obsd = true;
            __snap = c.pot();
        }
    }
