        // cannot change setUp requirement; therefore we create a new C instance here but still keep the one from setUp unused.

        Reverter rev = new Reverter();
        C c2 = new C();
        // c2.bank is set to msg.sender (this test contract). We need bank to be the reverting contract, but C's constructor sets bank to msg.sender
        // So to make bank = rev, we must deploy C from rev. Achieve by having rev deploy a C via a helper that exposes creation.
        C c3 = rev.deployC();

        // Work with c3 which has bank = address(rev)
        // Ensure we have enough balance for player to buy ticket and for test contract to fund c3
        uint256 ticket = 10;
