    // single test function: send an arbitrary positive amount 'amt' in one play call
    function run(uint256 amt) public payable {
        require(amt > 0);
        require(address(this).balance >= amt);

        uint before_c_balance = address(c).balance;
        // perform the state-changing call: one play with provided Ether
        c.play{value: amt}();

        uint after_c_balance = address(c).balance;

        // In original contract P, play requires exactly TICKET_AMOUNT, so when amt != TICKET_AMOUNT
        // the call reverts and c.balance remains unchanged; when amt == TICKET_AMOUNT the contract may
        // pay out but the contract's balance cannot increase by more than amt (it increases by exactly amt before payout).
        // Thus in P after_c_balance >= before_c_balance and after_c_balance - before_c_balance <= amt.
        // The mutant M (removed require) can accept arbitrary amt and then may pay out pot - FEE_AMOUNT which can make
        // after_c_balance increase by more than amt across states (observable as violation of the <= amt bound).

        assert(after_c_balance >= before_c_balance && after_c_balance - before_c_balance <= amt);
    }

    // receive to allow the test contract to hold Ether
    receive() external payable {}
}

